if (!defined('ABSPATH')) { exit; }
function emdop2_words($html){$text=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($html))));if($text==='')return 0;preg_match_all('/[\p{L}\p{M}]+(?:[’\x{27}’-][\p{L}\p{M}]+)*/u',$text,$m);return count($m[0]);}
function emdop2_cat($name,$slug,$en_name,$en_slug,$fallback_name=''){$term=get_term_by('slug',$slug,'category');if(!$term&&$fallback_name!=='')$term=get_term_by('name',$fallback_name,'category');if(!$term)$term=get_term_by('name',$name,'category');if(!$term){$made=wp_insert_term($name,'category',array('slug'=>$slug));if(is_wp_error($made))throw new Exception($made->get_error_message());$term=get_term((int)$made['term_id'],'category');}update_term_meta($term->term_id,'_en_US_name',$en_name);update_term_meta($term->term_id,'_en_US_slug',$en_slug);update_term_meta($term->term_id,'_en_US_published','1');return (int)$term->term_id;}
function emdop2_existing($key,$slug){$ids=get_posts(array('post_type'=>'post','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_emdo_authority_key','meta_value'=>$key));if($ids)return (int)$ids[0];$p=get_page_by_path($slug,OBJECT,'post');return $p?(int)$p->ID:0;}
$dir=(string)getenv('EMDO_PRIORITY_BATCH02_DIR');if(!$dir||!is_dir($dir))throw new Exception('Priority batch 02 data directory missing');$files=glob(trailingslashit($dir).'*.php');sort($files,SORT_NATURAL);if(count($files)!==5)throw new Exception('Expected five article files');
