'preserves'=>emdop2_cat('Conservas','conservas','Preserves','preserves'));
$product_slugs=array('ham'=>'jamones-paletas','meat'=>'carnes','vegetables'=>'hortalizas-verduras','oil'=>'aceites','preserves'=>'conservas');
$default=(int)get_option('emdo_default_blog_featured_attachment_id',0);if($default<=0||get_post_type($default)!=='attachment')throw new Exception('Central provisional image missing');$default_hash=(string)get_option('emdo_default_blog_featured_hash','');$admins=get_users(array('role'=>'administrator','number'=>1,'fields'=>'ID'));$author=$admins?(int)$admins[0]:1;$rows=array();
foreach($files as $file){$a=require $file;foreach(array('key','priority','slug','en_slug','topic','title','en_title','excerpt','en_excerpt','content','en_content','min_es','min_en') as $f){if(!isset($a[$f])||$a[$f]==='')throw new Exception(basename($file).' missing '.$f);}if(!isset($cats[$a['topic']]))throw new Exception('Unexpected topic '.$a['topic']);$product=$product_slugs[$a['topic']];$content=str_replace('__PRODUCT_CAT__',$product,$a['content']);$en=str_replace('__PRODUCT_CAT__',$product,$a['en_content']);
if($a['key']==='priority-07-how-long-meat-frozen'){$en=str_replace('<h2>How long can you freeze ground beef?</h2>','<p>If you are freezing a premium cut for a particular meal, label both the freezing date and the exact cut. This simple habit prevents an expensive steak from remaining forgotten for months merely because it is still frozen.</p><h2>How long can you freeze ground beef?</h2>',$en);}
if($a['key']==='priority-08-green-sprouted-potatoes'){$content=str_replace('<h2>Checklist: ¿me la como o la tiro?</h2>','<h2>¿Qué diferencia hay entre un ojo de la patata y un brote?</h2><p>Los llamados <strong>ojos</strong> son yemas naturales del tubérculo de las que pueden nacer nuevos tallos. Una patata recién comprada puede mostrar ojos sin haber desarrollado todavía brotes largos. Cuando esos ojos empiezan a crecer, la patata está utilizando sus reservas y la concentración de glicoalcaloides es especialmente relevante en el tejido del brote y alrededor de esas zonas. Por eso, cuando una patata todavía es firme y solo presenta un desarrollo incipiente, no basta con romper el brote con los dedos: conviene cortar también el ojo y una porción generosa de tejido circundante.</p><p>Esta distinción también ayuda a no desperdiciar patatas perfectamente normales. <strong>Tener ojos no es un defecto en sí mismo</strong>; todas las patatas los tienen. Lo que importa es si han comenzado a brotar de forma acusada y qué otras señales acompañan ese proceso.</p><h2>Checklist: ¿me la como o la tiro?</h2>',$content);$en=str_replace('<h2>Eat it or discard it? A practical table</h2>','<h2>What is the difference between a potato eye and a sprout?</h2><p>Potato <strong>eyes</strong> are natural buds from which new shoots can grow. A fresh potato can have visible eyes without having developed long sprouts. Once growth begins, the tuber is using its stored reserves, and glycoalkaloid concentrations are particularly relevant in the sprout and nearby tissue. When a potato is still firm and sprouting is only slight, do more than snap off the visible shoot: cut away the eye and a generous amount of surrounding tissue as well.</p><p>This distinction also prevents needless waste. <strong>Eyes themselves are normal anatomy</strong>; every potato has them. What matters is strong sprout development and whether it comes with extensive greening, shrivelling, damage or bitterness.</p><h2>Eat it or discard it? A practical table</h2>',$en);}
if($a['key']==='priority-09-olive-vs-sunflower-frying'){$content=str_replace('<h2>Conclusión</h2>','<h2>Qué cambia entre una fritura puntual y una fritura repetida</h2><p>No exige lo mismo una fritura rápida de una sola tanda que mantener aceite caliente mientras salen varias tandas consecutivas. Cuanto más tiempo permanece el aceite a alta temperatura y más ciclos acumula en contacto con oxígeno, agua y restos de alimento, más importante resulta su <strong>estabilidad frente a la oxidación</strong>. En ese escenario cobran especial sentido los aceites ricos en ácido oleico, como los aceites de oliva y el girasol alto oleico.</p><p>En una fritura puntual y poco prolongada, en cambio, la diferencia práctica puede depender mucho más del sabor que buscas, de que la temperatura sea correcta y de no dejar que el aceite humee. Eso explica por qué no existe una única botella obligatoria para todas las cocinas.</p><h2>¿Sirve añadir aceite nuevo a uno viejo para “renovarlo”?</h2><p>Añadir aceite fresco puede aumentar el volumen, pero <strong>no elimina los compuestos de degradación que ya se han formado</strong> en el aceite usado. Si el aceite presenta olor rancio, espuma anormal persistente, viscosidad excesiva, humo prematuro o un deterioro evidente, mezclarlo con aceite nuevo no lo recupera. Lo correcto es desecharlo y empezar con aceite limpio.</p><h2>Conclusión</h2>',$content);$en=str_replace('<h2>Bottom line</h2>','<h2>One-off frying versus repeated frying: why the answer changes</h2><p>A single quick batch of frying does not challenge an oil in the same way as keeping it hot through several consecutive batches. The longer oil remains at frying temperature, and the more cycles it experiences in contact with oxygen, moisture and food particles, the more its <strong>oxidative stability</strong> matters. That is where oils naturally rich in oleic acid — including olive oils and high-oleic sunflower — become particularly attractive.</p><p>For one short shallow-frying session, sensory preference and good technique may matter more to the home cook than small differences in long-term stability. Keeping the oil at the right temperature, avoiding visible smoke and not overcrowding the pan can have a larger effect on the result than switching between two otherwise suitable oils.</p><p>Repeated frying makes maintenance more important as well. Filter crumbs after use, protect cooled oil from light and air, and do not keep extending its life simply because it still looks reasonably clear. Degradation is not always visible.</p><h2>Can fresh oil revive old frying oil?</h2><p>Adding fresh oil increases the volume and dilutes the old oil, but it <strong>does not remove oxidation products and other compounds that have already formed</strong>. If used oil has developed rancid odour, persistent abnormal foaming, excessive viscosity, unusually early smoking or obvious deterioration, topping it up with new oil does not reset it. Discard the degraded oil and start again with a clean batch.</p><h2>Bottom line</h2>',$en);}
if($a['key']==='priority-10-open-can-fridge'){$content=str_replace('<h2>Una rutina de 30 segundos que evita casi todos los problemas</h2>','<h2>¿Hay que conservar también el líquido de cobertura?</h2><p>Depende del producto. En muchas verduras y legumbres, mantener el alimento cubierto por parte de su líquido original puede ayudar a evitar que la superficie se reseque mientras está refrigerada. Si prefieres escurrirlo o enjuagarlo antes de guardar, utiliza igualmente un recipiente cerrado y procura consumirlo pronto. No añadas agua del grifo para “rellenar” el tarro salvo que una receta lo requiera: cambiarías las condiciones del alimento sin prolongar su conservación.</p><p>Cuando el fabricante indica expresamente cómo conservar el contenido después de abrirlo, esa instrucción debe prevalecer sobre cualquier regla general.</p><h2>Una rutina de 30 segundos que evita casi todos los problemas</h2>',$content);$en=str_replace('<h2>A 30-second routine</h2>','<h2>Should you keep the packing liquid too?</h2><p>It depends on the food. For many vegetables and pulses, keeping the food covered by some of its original packing liquid can help prevent the exposed surface from drying during refrigeration. If you prefer to drain or rinse the food before storing it, use a closed container and plan to use it promptly. Do not add tap water simply to refill the container: that changes the food environment without extending its safe storage life.</p><p>If the manufacturer gives a specific after-opening instruction, that guidance takes priority over any general household rule.</p><h2>A 30-second routine</h2>',$en);}
$wes=emdop2_words($content);$wen=emdop2_words($en);if($wes<(int)$a['min_es']||$wen<(int)$a['min_en'])throw new Exception($a['key'].' too short ES='.$wes.'/'.(int)$a['min_es'].' EN='.$wen.'/'.(int)$a['min_en']);$existing=emdop2_existing($a['key'],$a['slug']);$new=$existing<=0;$post=array('post_type'=>'post','post_status'=>'publish','post_author'=>$author,'post_title'=>wp_strip_all_tags($a['title']),'post_name'=>sanitize_title($a['slug']),'post_excerpt'=>wp_strip_all_tags($a['excerpt']),'post_content'=>$content);if($existing)$post['ID']=$existing;$res=$existing?wp_update_post($post,true):wp_insert_post($post,true);if(is_wp_error($res))throw new Exception($a['key'].': '.$res->get_error_message());$id=(int)$res;wp_set_post_categories($id,array($guide,$cats[$a['topic']]),false);update_post_meta($id,'_emdo_authority_key',$a['key']);update_post_meta($id,'_emdo_priority_plan','38');update_post_meta($id,'_emdo_priority_order',(string)$a['priority']);update_post_meta($id,'_emdo_priority_batch','2');update_post_meta($id,'_en_US_post_title',wp_strip_all_tags($a['en_title']));update_post_meta($id,'_en_US_post_name',sanitize_title($a['en_slug']));update_post_meta($id,'_en_US_post_excerpt',wp_strip_all_tags($a['en_excerpt']));update_post_meta($id,'_en_US_post_content',$en);update_post_meta($id,'_en_US_ready','1');update_post_meta($id,'_en_US_published','1');update_post_meta($id,'_emdo_editorial_updated',gmdate('c'));$current=(int)get_post_thumbnail_id($id);$marked=(string)get_post_meta($id,'_emdo_uses_default_featured',true)==='1';if($new||$marked||$current<=0){update_post_meta($id,'_thumbnail_id',$default);update_post_meta($id,'_emdo_uses_default_featured','1');update_post_meta($id,'_emdo_editorial_image_approved_id',$default);delete_post_meta($id,'_emdo_editorial_image_approved_pexels_id');update_post_meta($id,'_emdo_editorial_cover_asset_id','emdo-blog-default-featured');update_post_meta($id,'_emdo_editorial_cover_brand_safe','1');update_post_meta($id,'_emdo_default_featured_hash',$default_hash);update_post_meta($id,'_emdo_default_featured_updated_at',gmdate('c'));}clean_post_cache($id);$rows[]=array('key'=>$a['key'],'priority'=>(int)$a['priority'],'id'=>$id,'status'=>get_post_status($id),'slug'=>get_post_field('post_name',$id),'en_slug'=>sanitize_title($a['en_slug']),'thumbnail_id'=>(int)get_post_thumbnail_id($id),'provisional'=>(string)get_post_meta($id,'_emdo_uses_default_featured',true),'words_es'=>$wes,'words_en'=>$wen,'min_es'=>(int)$a['min_es'],'min_en'=>(int)$a['min_en'],'topic'=>$a['topic'],'product_category'=>$product,'has_products_es'=>strpos($content,'[products')!==false,'has_products_en'=>strpos($en,'[products')!==false);}
if(count($rows)!==5)throw new Exception('Publish count mismatch');echo wp_json_encode(array('batch'=>'priority-02','default'=>$default,'posts'=>$rows),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT).PHP_EOL;
